// fly.toml is TOML, not TypeScript — shown here for reference alongside the Node.js app it configures
//
// app = 'my-typescript-api'
// primary_region = 'iad'          # US East (IAD) as primary region
//
// [build]
//   dockerfile = 'Dockerfile'
//
// [env]
//   PORT = '3000'
//   NODE_ENV = 'production'
//
// [http_service]
//   internal_port = 3000
//   force_https = true
//   auto_stop_machines = false    # keep alive; set true to stop on idle
//   auto_start_machines = true
//   min_machines_running = 1
//
// [[http_service.checks]]
//   grace_period = '10s'
//   interval = '30s'
//   method = 'GET'
//   path = '/health'
//   timeout = '5s'
//
// [[vm]]
//   memory = '512mb'
//   cpu_kind = 'shared'
//   cpus = 1

// Corresponding Express app (src/index.ts)
import express from 'express';

const app = express();
const PORT = Number(process.env.PORT ?? 3000);

app.get('/health', (_req, res) => {
  res.json({ status: 'ok', region: process.env.FLY_REGION ?? 'local' });
});

app.get('/api/hello', (_req, res) => {
  res.json({
    message: 'Hello from Fly.io!',
    region: process.env.FLY_REGION,
    machineId: process.env.FLY_MACHINE_ID,
  });
});

app.listen(PORT, '0.0.0.0', () => {
  console.log(`Listening on 0.0.0.0:${PORT}`);
});

// Dockerfile — multi-stage build to minimize final image size
// Place this in your project root alongside fly.toml
//
// ---- Stage 1: Build ----
// FROM node:20-alpine AS builder
// WORKDIR /app
//
// # Install dependencies first (layer cache optimization)
// COPY package.json package-lock.json ./
// RUN npm ci --frozen-lockfile
//
// # Copy source and compile TypeScript
// COPY tsconfig.json ./
// COPY src ./src
// RUN npx tsc --project tsconfig.json
//
// ---- Stage 2: Production image ----
// FROM node:20-alpine AS runner
// WORKDIR /app
// ENV NODE_ENV=production
//
// # Only copy production dependencies
// COPY package.json package-lock.json ./
// RUN npm ci --frozen-lockfile --omit=dev
//
// # Copy compiled output from build stage
// COPY --from=builder /app/dist ./dist
//
// # Run as non-root user
// RUN addgroup -S appgroup && adduser -S appuser -G appgroup
// USER appuser
//
// EXPOSE 3000
// CMD ["node", "dist/index.js"]

// Verify your image locally before deploying:
// docker build -t my-app . && docker run -p 3000:3000 my-app

// Deploy to Fly.io:
// fly deploy --remote-only

export {}; // make this a valid TypeScript module
